// 3Our Supermat API — validasi API key & normalisasi input untuk endpoint GENERATE
// API key (header X-Supermat-Key) divalidasi oleh node Webhook (Header Auth, credential "Supermat API Key (Header)").
// Request tanpa key yang benar sudah ditolak 403 sebelum sampai ke node ini. Key TIDAK ditulis di kode/repo.
const headers = $json.headers || {};
const body = $json.body || {};
const ok = true;

const keyword = String(body.keyword || body.query || '').trim();
let statusCode = 200, error = '';
if (!ok) { statusCode = 401; error = 'API key tidak valid. Kirim header X-Supermat-Key.'; }
else if (!keyword) { statusCode = 400; error = 'Field "keyword" wajib diisi.'; }

return [{ json: {
  ok: statusCode === 200, statusCode, error,
  keyword,
  geo: String(body.Geo || body.geo || 'ID').toUpperCase(),
  ln: String(body.Ln || body.ln || 'id').toLowerCase(),
  clientName: String(body.Client_Name || body.clientName || body.brandName || 'Brand Anda').trim(),
  niche: String(body.niche || '').trim(),
  tone: String(body.tone || '').trim(),
  wordCount: Math.min(Math.max(Number(body.wordCount) || 800, 400), 2500),
  requestId: String(body.requestId || ('req_' + Date.now().toString(36))),
  // --- Fase 6 & PRD F6b: CMS (opsional) untuk cek duplikat & internal link + opsi artikel ---
  cmsType: ['wordpress', 'wix', 'sanity', 'shopify'].includes(String(body.cmsType || '').toLowerCase()) ? String(body.cmsType).toLowerCase() : '',
  cms: body.cms && typeof body.cms === 'object' ? body.cms : {},
  options: normalizeOptions(body.options),
} }];

function normalizeOptions(o) {
  o = o && typeof o === 'object' ? o : {};
  const b = (v, d) => (v === undefined || v === null ? d : !!v);
  const n = (v, d, lo, hi) => { const x = Number(v); return Number.isFinite(x) ? Math.min(Math.max(x, lo), hi) : d; };
  const imageMode = ['none', 'auto', 'manual'].includes(o.imageMode) ? o.imageMode : (o.imagePrompts === false ? 'none' : 'auto');
  const imageCount = imageMode === 'none' ? 0 : n(o.imageCount, 3, 0, 6);
  const imageHero = b(o.imageHero, true);

  return {
    duplicateCheck: b(o.duplicateCheck, true), duplicateThreshold: n(o.duplicateThreshold, 0.7, 0.4, 0.95),
    internalLinks: b(o.internalLinks, true), maxInternal: n(o.maxInternal, 4, 0, 8), siteBaseUrl: String(o.siteBaseUrl || '').trim(),
    externalLinks: b(o.externalLinks, true), maxExternal: n(o.maxExternal, 2, 0, 5),
    excludeDomains: Array.isArray(o.excludeDomains) && o.excludeDomains.length ? o.excludeDomains.map(String) : ['facebook.com', 'instagram.com', 'tiktok.com', 'youtube.com', 'shopee.co.id', 'tokopedia.com', 'x.com', 'twitter.com', 'pinterest.com', 'linkedin.com'],
    imagePrompts: imageMode !== 'none',
    imageCount,
    imageMode,
    imageHero,
    imageStyle: String(o.imageStyle || 'foto editorial realistis, pencahayaan natural, warna hangat, tanpa teks atau logo di dalam gambar').trim(),
  };
}

// Fase 6 — Ambil daftar artikel yang sudah ada di CMS user (bila cms dikirim) lalu cek topik duplikat.
// Output = input (keyword, geo, ln, …) + existingPosts + duplicate flag, supaya node riset berikutnya tetap membaca $json.keyword.
const N = $input.first().json;
const H = this.helpers;

// ===== Helper CMS bersama (disisipkan oleh build-workflows.mjs) =====
// listExistingPosts(H, cmsType, cms, opts) -> [{ title, slug, url, publishedAt }]
// H = this.helpers (Code node). Semua error ditelan → [] supaya alur artikel tidak mati.
async function listExistingPosts(H, cmsType, cms, opts) {
  const o = Object.assign({ limit: 200, siteBaseUrl: '' }, opts || {});
  const base = String(o.siteBaseUrl || '').trim();
  const urlOf = (slug, direct) => direct || (base && slug ? base.replace(/\/+$/, '') + '/' + slug : '');
  const c = (cms || {})[cmsType] || {};
  try {
    if (cmsType === 'sanity') {
      const q = '*[_type == $t && defined(slug.current)] | order(coalesce(publishedAt, _createdAt) desc) [0...' + o.limit + ']{title, "slug": slug.current, publishedAt}';
      const r = await H.httpRequest({ method: 'POST', url: 'https://' + c.projectId + '.api.sanity.io/v2025-02-19/data/query/' + encodeURIComponent(c.dataset || 'production'),
        headers: Object.assign({ 'Content-Type': 'application/json' }, c.token ? { Authorization: 'Bearer ' + c.token } : {}), body: { query: q, params: { t: c.docType || 'post' } }, json: true });
      const pat = String(c.publicUrlPattern || '');
      return (r.result || []).filter(p => p.title).map(p => ({ title: p.title, slug: p.slug, url: urlOf(p.slug, pat && p.slug ? pat.replace('{slug}', p.slug) : ''), publishedAt: p.publishedAt || '' }));
    }
    if (cmsType === 'wordpress') {
      const auth = 'Basic ' + Buffer.from(String(c.user) + ':' + String(c.appPassword || '').replace(/\s+/g, '')).toString('base64');
      const out = [];
      for (let page = 1; page <= Math.ceil(o.limit / 100); page++) {
        const r = await H.httpRequest({ method: 'GET', url: c.url + '/wp-json/wp/v2/posts?status=publish&per_page=100&page=' + page + '&_fields=title,slug,link,date', headers: { Authorization: auth, 'User-Agent': 'Markimate/1.0' }, json: true });
        if (!Array.isArray(r) || !r.length) break;
        for (const p of r) out.push({ title: (p.title && p.title.rendered) || '', slug: p.slug, url: p.link || urlOf(p.slug), publishedAt: p.date || '' });
        if (r.length < 100) break;
      }
      return out;
    }
    if (cmsType === 'wix') {
      const r = await H.httpRequest({ method: 'GET', url: 'https://www.wixapis.com/blog/v3/posts?paging.limit=100&fieldsets=URL', headers: { Authorization: c.apiKey, 'wix-site-id': c.siteId }, json: true });
      return (r.posts || []).map(p => ({ title: p.title, slug: p.slug, url: p.url ? (p.url.base || '') + (p.url.path || '') : urlOf(p.slug), publishedAt: p.firstPublishedDate || '' }));
    }
    if (cmsType === 'shopify') {
      const r = await H.httpRequest({ method: 'POST', url: 'https://' + c.shop + '/admin/api/2026-07/graphql.json', headers: { 'X-Shopify-Access-Token': c.accessToken, 'Content-Type': 'application/json' },
        body: { query: '{ shop { primaryDomain { url } } articles(first: 100, sortKey: PUBLISHED_AT, reverse: true) { nodes { title handle publishedAt blog { handle } } } }' }, json: true });
      const d = (r.data || {}); const dom = ((d.shop || {}).primaryDomain || {}).url || ('https://' + c.shop);
      return ((d.articles || {}).nodes || []).map(a => ({ title: a.title, slug: a.handle, url: dom + '/blogs/' + ((a.blog || {}).handle || 'news') + '/' + a.handle, publishedAt: a.publishedAt || '' }));
    }
  } catch (e) { /* abaikan: tanpa daftar artikel */ }
  return [];
}

// --- kemiripan topik (token Jaccard-ish, dipakai cek duplikat & dedupe kandidat) ---
const STOPWORDS = new Set(['apa', 'itu', 'adalah', 'yang', 'dan', 'di', 'ke', 'dari', 'untuk', 'dengan', 'pada', 'cara', 'tips', 'panduan', 'lengkap', 'pengertian', 'arti', 'what', 'is', 'the', 'a', 'an', 'of', 'to', 'for', 'and', 'in', 'how', '2024', '2025', '2026', '2027', 'terbaru', 'contoh', 'jenis', 'manfaat', 'strategi', 'bisnis', 'agar', 'bagi', 'vs', 'atau']);
const topicTokens = s => String(s || '').toLowerCase().replace(/[^a-z0-9\s-]/g, ' ').replace(/-/g, ' ').split(/\s+/).filter(t => t.length > 1 && !STOPWORDS.has(t));
function topicSimilarity(a, b) {
  const ta = [...new Set(topicTokens(a))], tb = new Set(topicTokens(b));
  if (!ta.length || !tb.size) return 0;
  return ta.filter(t => tb.has(t)).length / ta.length;
}
function findDuplicate(keyword, posts, threshold) {
  let best = null;
  for (const p of posts || []) {
    const sim = Math.max(topicSimilarity(keyword, p.title), topicSimilarity(keyword, String(p.slug || '').replace(/-/g, ' ')));
    if (sim >= (threshold || 0.7) && (!best || sim > best.similarity)) best = Object.assign({ similarity: Number(sim.toFixed(2)) }, p);
  }
  return best;
}


let existingPosts = [];
const needPosts = N.cmsType && (N.options.duplicateCheck || N.options.internalLinks);
if (needPosts) existingPosts = await listExistingPosts(H, N.cmsType, N.cms, { limit: 200, siteBaseUrl: N.options.siteBaseUrl });

const dup = N.options.duplicateCheck ? findDuplicate(N.keyword, existingPosts, N.options.duplicateThreshold) : null;

return [{ json: Object.assign({}, N, {
  existingPosts,
  existingPostsChecked: existingPosts.length,
  needEnrich: !!((N.options.internalLinks && existingPosts.length) || N.options.externalLinks || N.options.imagePrompts),
  duplicate: !!dup,
  duplicateOf: dup ? { title: dup.title, slug: dup.slug, url: dup.url, similarity: dup.similarity } : null,
  statusCode: dup ? 409 : 200,
  error: dup ? 'Topik mirip sudah ada di CMS: ' + dup.title : '',
}) }];

// Pilih kandidat keyword dari Google Trends (rising + top) yang masih relevan dengan seed keyword.
// Seed keyword SELALU jadi kandidat pertama, jadi alur tidak pernah mati walau Trends kosong/error.
const N = $('Auth & Normalize').first().json;
let t = {}; try { t = $('Riset Google Trends').first().json || {}; } catch (e) {}
const ac = $input.first().json || {}; // SerpAPI google_autocomplete
const rq = t.related_queries || {};
const pool = [
  ...(rq.rising || []), ...(rq.top || []),
].map(x => String(x.query || '').trim()).concat((ac.suggestions || []).map(s => String(s.value || '').trim())).filter(Boolean);

const seed = N.keyword.toLowerCase();
const stop = new Set(['di', 'ke', 'dari', 'yang', 'dan', 'untuk', 'dengan', 'ada', 'adalah', 'itu', 'ini', 'cara', 'tips', 'info', 'the', 'a', 'an', 'of', 'for', 'in', 'on', 'to']);
const terms = [seed, ...seed.split(/\s+/).map(w => w.replace(/[^a-z0-9]/g, '')).filter(w => w.length > 2 && !stop.has(w))];
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const matches = q => terms.some(tm => tm.includes(' ') ? q.includes(tm) : new RegExp('\\b' + esc(tm) + '\\b', 'i').test(q));

const matched = pool.filter(q => q.toLowerCase() !== seed && matches(q.toLowerCase()));
const uniq = [...new Set([N.keyword, ...matched])].slice(0, 4);
return uniq.map((q, i) => ({ json: { query: q, isSeed: i === 0, source: i === 0 ? 'seed' : 'trends/autocomplete', trendsError: t.error ? String(t.error.message || t.error) : '' } }));

// Gabungkan metrik Ahrefs (RapidAPI) per kandidat, pilih target keyword terbaik.
// Prioritas: volume terbesar dengan difficulty valid; fallback: seed keyword tanpa metrik.
const N = $('Auth & Normalize').first().json;
const cands = $('Pilih Kandidat').all().map(i => i.json);
const metrics = $input.all().map(i => i.json || {});
const num = v => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

const rows = cands.map((c, i) => {
  const m = metrics[i] || {}; const d = m.data || m || {};
  const diffRaw = d.difficulty;
  return {
    query: c.query, isSeed: !!c.isSeed,
    searchVolume: num(d.globalSearchVolume ?? d.searchVolume ?? d.volume),
    difficulty: (diffRaw === null || diffRaw === undefined || diffRaw === 'null' || diffRaw === '') ? null : num(diffRaw),
    trafficPotential: num(d.trafficPotential),
    cpc: num(d.cpc),
    error: m.error ? String(m.error.message || m.error) : '',
  };
});
const valid = rows.filter(r => r.searchVolume > 0).sort((a, b) => b.searchVolume - a.searchVolume);
const seedRow = rows.find(r => r.isSeed) || { query: N.keyword, searchVolume: 0, difficulty: null, trafficPotential: 0 };
const best = valid[0] || seedRow;

return [{ json: {
  ...N,
  targetKeyword: best.query,
  searchVolume: best.searchVolume,
  difficulty: best.difficulty,
  trafficPotential: best.trafficPotential,
  seedMetrics: { searchVolume: seedRow.searchVolume, difficulty: seedRow.difficulty },
  candidates: rows,
  relatedQueries: rows.map(r => r.query).filter(q => q !== best.query),
  geoLower: String(N.geo || 'ID').toLowerCase(),
} }];

// Parse output AI Agent -> Unified Article Payload yang dikembalikan ke pemanggil API.
const T = $('Tentukan Target').first().json;
const ai = $input.first().json || {};

function safeParse(str) {
  if (!str) return null;
  if (typeof str === 'object') return str;
  const s = String(str);
  try { return JSON.parse(s); } catch (e) {}
  const clean = s.replace(/```json/gi, '').replace(/```/g, '').trim();
  const a = clean.indexOf('{'), b = clean.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(clean.slice(a, b + 1)); } catch (e) {} }
  return null;
}
const raw = ai.output ?? ai.text ?? ai;
const parsed = safeParse(raw) || {};

const slugify = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 90);
const title = String(parsed.title || '').trim();
const body = String(parsed.body || parsed.bodyMarkdown || parsed.content || '').trim();
if (!title || !body) {
  return [{ json: { ok: false, statusCode: 502, error: 'AI tidak mengembalikan artikel yang valid. Coba lagi.', raw: typeof raw === 'string' ? raw.slice(0, 500) : raw, requestId: T.requestId } }];
}
const excerpt = String(parsed.excerpt || body.replace(/[#*_>`-]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 160)).trim();
const words = body.split(/\s+/).filter(Boolean).length;
const keywords = [...new Set([T.targetKeyword, T.keyword, ...(T.relatedQueries || [])].filter(Boolean))].slice(0, 8);

return [{ json: {
  ok: true, statusCode: 200,
  status: 'ok',
  requestId: T.requestId,
  keyword: T.keyword,
  clientName: T.clientName,
  geo: T.geo, ln: T.ln,
  article: {
    title,
    slug: slugify(parsed.slug) || slugify(title),
    excerpt,
    bodyMarkdown: body,
    keywords,
    primaryKeyword: T.targetKeyword,
    searchVolume: T.searchVolume,
    difficulty: T.difficulty,
    trafficPotential: T.trafficPotential,
    wordCount: words,
    language: T.ln,
    generatedAt: new Date().toISOString(),
    model: 'gemini',
  },
  research: { candidates: T.candidates, relatedQueries: T.relatedQueries },
} }];

// Fase 6 — Susun prompt Gemini untuk: internal link (artikel lama di CMS), external link (hasil Google), dan prompt gambar.
// Input node ini = respons SerpAPI "Cari Sumber Eksternal" (boleh error/kosong). Artikel diambil dari "Susun Artikel".
const R = $('Susun Artikel').first().json;
const D = $('Cek Duplikat').first().json;
const O = D.options || {};
const A = R.article || {};
const S = $input.first().json || {};

// ===== Helper CMS bersama (disisipkan oleh build-workflows.mjs) =====
// listExistingPosts(H, cmsType, cms, opts) -> [{ title, slug, url, publishedAt }]
// H = this.helpers (Code node). Semua error ditelan → [] supaya alur artikel tidak mati.
async function listExistingPosts(H, cmsType, cms, opts) {
  const o = Object.assign({ limit: 200, siteBaseUrl: '' }, opts || {});
  const base = String(o.siteBaseUrl || '').trim();
  const urlOf = (slug, direct) => direct || (base && slug ? base.replace(/\/+$/, '') + '/' + slug : '');
  const c = (cms || {})[cmsType] || {};
  try {
    if (cmsType === 'sanity') {
      const q = '*[_type == $t && defined(slug.current)] | order(coalesce(publishedAt, _createdAt) desc) [0...' + o.limit + ']{title, "slug": slug.current, publishedAt}';
      const r = await H.httpRequest({ method: 'POST', url: 'https://' + c.projectId + '.api.sanity.io/v2025-02-19/data/query/' + encodeURIComponent(c.dataset || 'production'),
        headers: Object.assign({ 'Content-Type': 'application/json' }, c.token ? { Authorization: 'Bearer ' + c.token } : {}), body: { query: q, params: { t: c.docType || 'post' } }, json: true });
      const pat = String(c.publicUrlPattern || '');
      return (r.result || []).filter(p => p.title).map(p => ({ title: p.title, slug: p.slug, url: urlOf(p.slug, pat && p.slug ? pat.replace('{slug}', p.slug) : ''), publishedAt: p.publishedAt || '' }));
    }
    if (cmsType === 'wordpress') {
      const auth = 'Basic ' + Buffer.from(String(c.user) + ':' + String(c.appPassword || '').replace(/\s+/g, '')).toString('base64');
      const out = [];
      for (let page = 1; page <= Math.ceil(o.limit / 100); page++) {
        const r = await H.httpRequest({ method: 'GET', url: c.url + '/wp-json/wp/v2/posts?status=publish&per_page=100&page=' + page + '&_fields=title,slug,link,date', headers: { Authorization: auth, 'User-Agent': 'Markimate/1.0' }, json: true });
        if (!Array.isArray(r) || !r.length) break;
        for (const p of r) out.push({ title: (p.title && p.title.rendered) || '', slug: p.slug, url: p.link || urlOf(p.slug), publishedAt: p.date || '' });
        if (r.length < 100) break;
      }
      return out;
    }
    if (cmsType === 'wix') {
      const r = await H.httpRequest({ method: 'GET', url: 'https://www.wixapis.com/blog/v3/posts?paging.limit=100&fieldsets=URL', headers: { Authorization: c.apiKey, 'wix-site-id': c.siteId }, json: true });
      return (r.posts || []).map(p => ({ title: p.title, slug: p.slug, url: p.url ? (p.url.base || '') + (p.url.path || '') : urlOf(p.slug), publishedAt: p.firstPublishedDate || '' }));
    }
    if (cmsType === 'shopify') {
      const r = await H.httpRequest({ method: 'POST', url: 'https://' + c.shop + '/admin/api/2026-07/graphql.json', headers: { 'X-Shopify-Access-Token': c.accessToken, 'Content-Type': 'application/json' },
        body: { query: '{ shop { primaryDomain { url } } articles(first: 100, sortKey: PUBLISHED_AT, reverse: true) { nodes { title handle publishedAt blog { handle } } } }' }, json: true });
      const d = (r.data || {}); const dom = ((d.shop || {}).primaryDomain || {}).url || ('https://' + c.shop);
      return ((d.articles || {}).nodes || []).map(a => ({ title: a.title, slug: a.handle, url: dom + '/blogs/' + ((a.blog || {}).handle || 'news') + '/' + a.handle, publishedAt: a.publishedAt || '' }));
    }
  } catch (e) { /* abaikan: tanpa daftar artikel */ }
  return [];
}

// --- kemiripan topik (token Jaccard-ish, dipakai cek duplikat & dedupe kandidat) ---
const STOPWORDS = new Set(['apa', 'itu', 'adalah', 'yang', 'dan', 'di', 'ke', 'dari', 'untuk', 'dengan', 'pada', 'cara', 'tips', 'panduan', 'lengkap', 'pengertian', 'arti', 'what', 'is', 'the', 'a', 'an', 'of', 'to', 'for', 'and', 'in', 'how', '2024', '2025', '2026', '2027', 'terbaru', 'contoh', 'jenis', 'manfaat', 'strategi', 'bisnis', 'agar', 'bagi', 'vs', 'atau']);
const topicTokens = s => String(s || '').toLowerCase().replace(/[^a-z0-9\s-]/g, ' ').replace(/-/g, ' ').split(/\s+/).filter(t => t.length > 1 && !STOPWORDS.has(t));
function topicSimilarity(a, b) {
  const ta = [...new Set(topicTokens(a))], tb = new Set(topicTokens(b));
  if (!ta.length || !tb.size) return 0;
  return ta.filter(t => tb.has(t)).length / ta.length;
}
function findDuplicate(keyword, posts, threshold) {
  let best = null;
  for (const p of posts || []) {
    const sim = Math.max(topicSimilarity(keyword, p.title), topicSimilarity(keyword, String(p.slug || '').replace(/-/g, ' ')));
    if (sim >= (threshold || 0.7) && (!best || sim > best.similarity)) best = Object.assign({ similarity: Number(sim.toFixed(2)) }, p);
  }
  return best;
}


// --- kandidat internal: artikel lama paling mirip dengan topik (maks 30) ---
const existing = (D.existingPosts || []).filter(p => p.url && p.title && String(p.slug || '') !== String(A.slug || ''));
const scored = existing.map(p => ({ p, s: topicSimilarity(p.title, A.title + ' ' + (A.keywords || []).join(' ')) })).sort((a, b) => b.s - a.s);
const internal = (O.internalLinks ? scored.slice(0, 30) : []).map(({ p }, i) => ({ id: 'I' + (i + 1), title: p.title, url: p.url }));

// --- kandidat eksternal: organic results SerpAPI minus domain yang dikecualikan & domain brand sendiri ---
const excl = (O.excludeDomains || []).map(d => String(d).toLowerCase());
const own = (() => { try { return new URL(O.siteBaseUrl).hostname.replace(/^www\./, ''); } catch (e) { return ''; } })();
const host = u => { try { return new URL(u).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { return ''; } };
const external = (O.externalLinks ? (S.organic_results || []) : []).filter(r => r.link && host(r.link) && !excl.some(d => host(r.link).endsWith(d)) && (!own || !host(r.link).endsWith(own)))
  .slice(0, 8).map((r, i) => ({ id: 'E' + (i + 1), title: r.title, url: r.link, domain: host(r.link), snippet: String(r.snippet || '').slice(0, 160) }));

// Ekstrak bagian H2 dan ringkasan untuk pemilihan gambar kontekstual (PRD F6b §3.3)
const h2Sections = [];
const lines = String(A.bodyMarkdown || '').split('\n');
let curH2 = null;
let curText = [];

for (const line of lines) {
  const h2Match = line.match(/^##\s+(.+)$/);
  if (h2Match) {
    if (curH2) {
      const summary = curText.join(' ').replace(/[\r\n]+/g, ' ').trim().slice(0, 300);
      h2Sections.push({ index: h2Sections.length + 1, title: curH2, summary });
    }
    curH2 = h2Match[1].trim();
    curText = [];
  } else if (curH2 && line.trim() && !line.startsWith('#')) {
    if (curText.length < 3) curText.push(line.trim());
  }
}
if (curH2) {
  const summary = curText.join(' ').replace(/[\r\n]+/g, ' ').trim().slice(0, 300);
  h2Sections.push({ index: h2Sections.length + 1, title: curH2, summary });
}

const wantImages = O.imageMode === 'none' ? 0 : (O.imageCount !== undefined ? Number(O.imageCount) : (O.imagePrompts ? 3 : 0));
const heroActive = wantImages > 0 && O.imageHero !== false;
const inlineCount = heroActive ? Math.max(0, wantImages - 1) : wantImages;
const body = String(A.bodyMarkdown || '').slice(0, 14000);
const lang = (D.ln || 'id') === 'id' ? 'Bahasa Indonesia' : D.ln;

const prompt = `Kamu editor SEO. Diberikan ARTIKEL (markdown) dan daftar kandidat tautan. Kembalikan HANYA JSON valid dengan bentuk:
{"internal":[{"anchor":"","url":"","title":""}],"external":[{"anchor":"","url":"","domain":""}],"imagePrompts":[{"idx":0,"placement":"hero","sectionTitle":"","prompt":"","alt":""}]}

ATURAN TAUTAN
- "anchor" HARUS potongan teks yang muncul PERSIS (huruf sama) di paragraf isi artikel — bukan di judul/heading, bukan di dalam teks yang sudah menjadi link [..](..), 2–6 kata, alami, relevan dengan halaman tujuan.
- internal: maksimal ${O.maxInternal} tautan, pilih hanya kandidat yang benar-benar relevan secara topik; url & title disalin persis dari kandidat. Satu url hanya sekali. Bila tidak ada yang relevan, kembalikan [].
- external: maksimal ${O.maxExternal} tautan ke sumber kredibel (lembaga resmi, media besar, riset); url disalin persis dari kandidat; jangan ke kompetitor langsung brand "${D.clientName}". Bila tidak ada yang layak, [].
- Jangan mengubah artikel; hanya kembalikan daftar.

ATURAN GAMBAR (buat tepat ${wantImages} item; bila ${wantImages} = 0 kembalikan [])
${heroActive ? '- Item pertama (idx 0): placement "hero", sectionTitle "Hero" (gambar utama 16:9, mewakili keseluruhan topik artikel).' : ''}
${inlineCount > 0 ? `- Pilih ${inlineCount} bagian H2 paling layak diilustrasikan dari DAFTAR BAGIAN H2 di bawah:
  * placement HARUS berbentuk "h2:<index>" (contoh: "h2:1", "h2:3") sesuai nomor index H2 terpilih, serta tuliskan "sectionTitle"-nya.
  * Maksimal 1 gambar per H2.
  * Prioritaskan bagian yang berisi proses, langkah, perbandingan, atau objek konkret.
  * HINDARI bagian FAQ dan kesimpulan.
  * Sebar merata di sepanjang artikel dan jangan berurutan kecuali artikel pendek.` : ''}
- "prompt" dalam bahasa Inggris untuk model text-to-image AI, deskriptif & konkret DITULIS DARI ISI BAGIAN ITU (bukan dari judul artikel), gaya: ${O.imageStyle}. Tanpa teks, logo, watermark, atau wajah tokoh nyata. Sesuaikan konteks Indonesia bila relevan.
- "alt" dalam ${lang}, 6–14 kata, deskriptif sesuai ilustrasi bagian tersebut, mengandung kata kunci bila alami.

ARTIKEL
Judul: ${A.title}
Keyword utama: ${A.primaryKeyword || D.keyword}
---
${body}
---

DAFTAR BAGIAN H2 (UNTUK PEMILIHAN GAMBAR KONTEKSTUAL)
${h2Sections.length ? h2Sections.map(s => `[h2:${s.index}] ${s.title} — Ringkasan: ${s.summary}`).join('\n') : '(artikel tidak memiliki sub-bab H2)'}

KANDIDAT INTERNAL (artikel lama di situs yang sama)
${internal.length ? internal.map(i => `${i.id} | ${i.title} | ${i.url}`).join('\n') : '(tidak ada)'}

KANDIDAT EKSTERNAL (hasil pencarian Google)
${external.length ? external.map(e => `${e.id} | ${e.domain} | ${e.title} | ${e.url} | ${e.snippet}`).join('\n') : '(tidak ada)'}`;

return [{ json: {
  skip: !internal.length && !external.length && !wantImages,
  prompt, internalCandidates: internal, externalCandidates: external, wantImages,
  geminiBody: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json', temperature: 0.2, maxOutputTokens: 2048 } },
} }];

// Fase 6 — Terapkan hasil Gemini: sisipkan internal/external link ke markdown + placeholder gambar, lalu kembalikan respons generate.
const R = JSON.parse(JSON.stringify($('Susun Artikel').first().json));
const P = $('Siapkan Prompt Link').first().json;
const D = $('Cek Duplikat').first().json;
const O = D.options || {};
const G = $input.first().json || {};

// --- parse JSON Gemini (toleran) ---
let parsed = null;
try {
  const txt = (((G.candidates || [])[0] || {}).content || {}).parts?.map(p => p.text || '').join('') || '';
  const clean = String(txt).replace(/```json/gi, '').replace(/```/g, '').trim();
  const a = clean.indexOf('{'), b = clean.lastIndexOf('}');
  parsed = JSON.parse(a >= 0 && b > a ? clean.slice(a, b + 1) : clean);
} catch (e) { parsed = null; }
const warnings = [];
if (!parsed) warnings.push('Link & prompt gambar dilewati: ' + (G.error ? String(G.error.message || G.error).slice(0, 140) : 'respons AI tidak valid'));
parsed = parsed || { internal: [], external: [], imagePrompts: [] };

const A = R.article;
let md = String(A.bodyMarkdown || '');
const lines = md.split('\n');
const isHeading = l => /^\s*#{1,6}\s/.test(l);
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const usedUrls = new Set();
const applied = { internal: [], external: [] };

function applyLink(item, type, allowed, max) {
  if (applied[type].length >= max) return;
  const anchor = String(item.anchor || '').trim(); const url = String(item.url || '').trim();
  if (!anchor || !url || usedUrls.has(url)) return;
  const cand = allowed.find(c => c.url === url); if (!cand) return; // url harus dari kandidat (anti halusinasi)
  const re = new RegExp('(^|[^\\[\\w])(' + esc(anchor) + ')(?![^\\[]*\\]\\()(?!\\w)');
  for (let i = 0; i < lines.length; i++) {
    if (isHeading(lines[i]) || /^\s*!\[/.test(lines[i]) || !re.test(lines[i])) continue;
    lines[i] = lines[i].replace(re, (m, pre, a) => pre + '[' + a + '](' + url + ')');
    usedUrls.add(url);
    applied[type].push(type === 'internal' ? { anchor, url, title: cand.title || item.title || '' } : { anchor, url, domain: cand.domain || '' });
    return;
  }
}
for (const it of (Array.isArray(parsed.internal) ? parsed.internal : [])) applyLink(it, 'internal', P.internalCandidates || [], O.maxInternal || 0);
for (const it of (Array.isArray(parsed.external) ? parsed.external : [])) applyLink(it, 'external', P.externalCandidates || [], O.maxExternal || 0);

// --- prompt gambar + placeholder di markdown (PRD F6b §3.3) ---
const want = (O.imageMode === 'none') ? 0 : (P.wantImages || 0);
const heroActive = want > 0 && O.imageHero !== false;
const rawPrompts = (O.imageMode === 'none') ? [] : (Array.isArray(parsed.imagePrompts) ? parsed.imagePrompts : []).filter(p => p && p.prompt);

const h2Idx = lines.map((l, i) => (/^\s*##\s/.test(l) ? i : -1)).filter(i => i >= 0);
const totalH2 = h2Idx.length;
const usedH2 = new Set();
let usedIntro = false;
const validPrompts = [];
const inserts = []; // [lineIndex, text]

for (let i = 0; i < Math.min(rawPrompts.length, want); i++) {
  const p = rawPrompts[i];
  const isHero = (i === 0 && heroActive) || (p.placement === 'hero' && heroActive);
  if (isHero) {
    validPrompts.push({
      idx: validPrompts.length,
      placement: 'hero',
      sectionTitle: p.sectionTitle || 'Hero',
      prompt: String(p.prompt).trim(),
      alt: String(p.alt || A.title).trim(),
      aspect: '16:9'
    });
    continue;
  }

  // Parse nomor H2 target ("h2:<n>" atau "after_h2:<n>")
  const m = String(p.placement || '').match(/^(?:after_)?h2:(\d+)$/i);
  let k = m ? Number(m[1]) : 0;

  // Validasi: di luar jangkauan atau H2 duplikat -> cari H2 kosong terdekat (§3.3 butir 6)
  if (k < 1 || k > totalH2 || usedH2.has(k)) {
    let nearestEmpty = null;
    let minDiff = Infinity;
    for (let candidate = 1; candidate <= totalH2; candidate++) {
      if (!usedH2.has(candidate)) {
        const diff = Math.abs(candidate - (k || 1));
        if (diff < minDiff) {
          minDiff = diff;
          nearestEmpty = candidate;
        }
      }
    }

    if (nearestEmpty !== null) {
      if (k > 0) warnings.push(`Penempatan gambar dialihkan dari ${p.placement} ke h2:${nearestEmpty} (H2 kosong terdekat).`);
      k = nearestEmpty;
    } else if (!usedIntro) {
      // Fallback: sisa gambar ditempatkan setelah paragraf ke-2 intro (§3.3 butir 4)
      k = 0;
      usedIntro = true;
      warnings.push(`Jumlah H2 (${totalH2}) lebih sedikit dari gambar yang diminta; sisa gambar ditempatkan setelah intro.`);
    } else {
      // Tidak ada ruang lagi -> gambar tidak dibuat, kredit tidak dipotong (§3.3 butir 4)
      warnings.push(`Bagian artikel tidak mencukupi untuk gambar tambahan; gambar idx ${i} dilewati.`);
      continue;
    }
  }

  if (k > 0) usedH2.add(k);

  const curIdx = validPrompts.length;
  const placement = k > 0 ? `h2:${k}` : 'intro';
  const promptObj = {
    idx: curIdx,
    placement,
    sectionTitle: p.sectionTitle || (k > 0 ? `Section ${k}` : 'Intro'),
    prompt: String(p.prompt).trim(),
    alt: String(p.alt || A.title).trim(),
    aspect: '4:3'
  };
  validPrompts.push(promptObj);

  // Cari posisi baris di markdown
  let at = lines.length;
  if (k >= 1) {
    at = h2Idx[k - 1] + 1;
    while (at < lines.length && !lines[at].trim()) at++;
    while (at < lines.length && lines[at].trim() && !isHeading(lines[at])) at++;
  } else {
    let paras = 0;
    for (let l = 0; l < lines.length; l++) {
      if (isHeading(lines[l])) break;
      if (lines[l].trim() && (l + 1 >= lines.length || !lines[l + 1].trim())) {
        if (++paras === 2) { at = l + 1; break; }
      }
    }
  }

  inserts.push([at, '\n![' + promptObj.alt.replace(/[\[\]]/g, '') + '](markimate:image:' + curIdx + ')\n']);
}

if (want > 0 && !validPrompts.length) {
  warnings.push('AI tidak mengembalikan prompt gambar yang valid; artikel dibuat tanpa gambar.');
}

inserts.sort((a, b) => b[0] - a[0]);
for (const [at, text] of inserts) lines.splice(at, 0, text);
md = lines.join('\n').replace(/\n{3,}/g, '\n\n');
const prompts = validPrompts;

A.bodyMarkdown = md;
A.links = applied;
A.imagePrompts = prompts;
A.wordCount = md.replace(/!\[[^\]]*\]\([^)]*\)/g, '').split(/\s+/).filter(Boolean).length;
R.research = Object.assign({}, R.research, { existingPostsChecked: D.existingPostsChecked || 0, internalCandidates: (P.internalCandidates || []).length, externalCandidates: (P.externalCandidates || []).length });
R.warnings = warnings;
return [{ json: R }];

// 3Our Supermat API — validasi API key & normalisasi input untuk endpoint PUBLISH
// Body: { cmsType: 'wordpress'|'wix'|'sanity'|'shopify', action: 'draft'|'publish', cms: {...kredensial user...}, article: {...}, postId?: '' }
// API key (header X-Supermat-Key) divalidasi oleh node Webhook (Header Auth, credential "Supermat API Key (Header)").
// Request tanpa key yang benar sudah ditolak 403 sebelum sampai ke node ini. Key TIDAK ditulis di kode/repo.
const headers = $json.headers || {};
const body = $json.body || {};
const ok = true;

const cmsType = String(body.cmsType || body.CMS_Type || '').toLowerCase().trim();
const action = String(body.action || '').toLowerCase() === 'publish' ? 'publish' : 'draft';
const cmsIn = body.cms || {};
const str = v => String(v ?? '').trim();
const cms = {
  wordpress: {
    url: str((cmsIn.wordpress || {}).url || body.wpUrl).replace(/\/+$/, ''),
    user: str((cmsIn.wordpress || {}).user || body.wpUser),
    appPassword: str((cmsIn.wordpress || {}).appPassword || body.wpPass),
  },
  wix: {
    siteId: str((cmsIn.wix || {}).siteId || body.wixSiteId),
    apiKey: str((cmsIn.wix || {}).apiKey || body.wixKey),
    memberId: str((cmsIn.wix || {}).memberId || body.wixMemberId),
  },
  sanity: {
    projectId: str((cmsIn.sanity || {}).projectId || body.projectId),
    dataset: str((cmsIn.sanity || {}).dataset || body.dataset) || 'production',
    token: str((cmsIn.sanity || {}).token || body.authToken),
    studioUrl: str((cmsIn.sanity || {}).studioUrl || body.studioUrl),
    docType: str((cmsIn.sanity || {}).docType) || 'post',
    bodyField: str((cmsIn.sanity || {}).bodyField) || 'body',
    publicUrlPattern: str((cmsIn.sanity || {}).publicUrlPattern),
    // Fase 6: mapping field dokumen
    authorId: str((cmsIn.sanity || {}).authorId),
    autoCreateAuthor: (cmsIn.sanity || {}).autoCreateAuthor !== false,
    categoryIds: Array.isArray((cmsIn.sanity || {}).categoryIds) ? (cmsIn.sanity || {}).categoryIds.map(str).filter(Boolean) : [],
    publishedAtField: str((cmsIn.sanity || {}).publishedAtField) || 'publishedAt',
    mainImageField: str((cmsIn.sanity || {}).mainImageField) || 'mainImage',
    excerptField: str((cmsIn.sanity || {}).excerptField) || 'excerpt',
  },
  shopify: {
    shop: str((cmsIn.shopify || {}).shop).toLowerCase().replace(/^https?:\/\//, '').replace(/\/.*$/, ''),
    accessToken: str((cmsIn.shopify || {}).accessToken),
    clientId: str((cmsIn.shopify || {}).clientId),
    clientSecret: str((cmsIn.shopify || {}).clientSecret),
    blogId: str((cmsIn.shopify || {}).blogId),
    authorName: str((cmsIn.shopify || {}).authorName),
  },
};
if (cmsIn.wordpress) { cms.wordpress.categoryIds = Array.isArray(cmsIn.wordpress.defaultCategoryIds) ? cmsIn.wordpress.defaultCategoryIds.map(Number).filter(Boolean) : []; cms.wordpress.authorId = Number(cmsIn.wordpress.authorId) || 0; }

// --- Fase 6: gambar AI (hanya Sanity & WordPress yang bisa menerima upload) ---
const optIn = body.options && typeof body.options === 'object' ? body.options : {};
const IMAGE_CMS = ['sanity', 'wordpress'];
const warnings = [];
const prompts = body.article && Array.isArray(body.article.imagePrompts) ? body.article.imagePrompts.filter(p => p && p.prompt) : [];
let makeImages = optIn.images !== false && prompts.length > 0 && !!(body.article && body.article.title);
if (makeImages && !IMAGE_CMS.includes(cmsType)) { makeImages = false; warnings.push((cmsType === 'wix' ? 'Wix' : cmsType === 'shopify' ? 'Shopify' : cmsType) + ': upload gambar belum didukung, artikel dikirim tanpa gambar.'); }
const stripPlaceholders = md => String(md || '').replace(/^\s*!\[[^\]]*\]\(markimate:image:\d+\)\s*$/gm, '').replace(/\n{3,}/g, '\n\n');
const article = body.article && typeof body.article === 'object' ? body.article : null;
const postId = str(body.postId || body.draftDocId || body.draftPostId);

let statusCode = 200, error = '';
if (!ok) { statusCode = 401; error = 'API key tidak valid. Kirim header X-Supermat-Key.'; }
else if (!['wordpress', 'wix', 'sanity', 'shopify'].includes(cmsType)) { statusCode = 400; error = 'cmsType harus wordpress, wix, sanity, atau shopify.'; }
else if (!article && !postId) { statusCode = 400; error = 'Field "article" wajib diisi (atau postId untuk publish draf yang sudah ada).'; }
else if (article && (!str(article.title) || !str(article.bodyMarkdown || article.body))) { statusCode = 400; error = 'article.title dan article.bodyMarkdown wajib diisi.'; }
else if (cmsType === 'wordpress' && (!cms.wordpress.url || !cms.wordpress.user || !cms.wordpress.appPassword)) { statusCode = 400; error = 'Kredensial WordPress belum lengkap (url, user, appPassword).'; }
else if (cmsType === 'wix' && (!cms.wix.siteId || !cms.wix.apiKey)) { statusCode = 400; error = 'Kredensial Wix belum lengkap (siteId, apiKey).'; }
else if (cmsType === 'sanity' && (!cms.sanity.projectId || !cms.sanity.token)) { statusCode = 400; error = 'Kredensial Sanity belum lengkap (projectId, token).'; }
else if (cmsType === 'sanity' && (!/^[a-z0-9]+$/i.test(cms.sanity.projectId) || !/^[a-z0-9_-]+$/i.test(cms.sanity.dataset) || !/^[A-Za-z_][A-Za-z0-9_.-]*$/.test(cms.sanity.docType) || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(cms.sanity.bodyField))) { statusCode = 400; error = 'Format Sanity tidak valid: Project ID (huruf/angka), dataset (huruf kecil, angka, - _), docType & bodyField (nama field).'; }
else if (cmsType === 'shopify' && (!cms.shopify.shop || (!cms.shopify.accessToken && !(cms.shopify.clientId && cms.shopify.clientSecret)))) { statusCode = 400; error = 'Kredensial Shopify belum lengkap (shop + accessToken, atau shop + clientId + clientSecret).'; }
if (cms.wordpress.url && !/^https?:\/\//i.test(cms.wordpress.url)) cms.wordpress.url = 'https://' + cms.wordpress.url;

return [{ json: {
  ok: statusCode === 200, statusCode, error,
  cmsType, action, cms, postId,
  article: article ? Object.assign({}, article, { bodyMarkdown: makeImages ? str(article.bodyMarkdown || article.body) : stripPlaceholders(article.bodyMarkdown || article.body), imagePrompts: makeImages ? prompts.slice(0, Math.min(Number(optIn.imageCount) || 3, 3)) : [] }) : null,
  makeImages, images: [], warnings,
  options: { images: makeImages, imageStyle: str(optIn.imageStyle) },
  clientName: str(body.clientName || body.Client_Name || 'Brand Anda'),
  requestId: str(body.requestId) || ('pub_' + Date.now().toString(36)),
} }];

// Fase 6 — Satu item per prompt gambar untuk node "Nano Banana" (Gemini image). idx 0 = hero 16:9, lainnya 4:3.
const N = $input.first().json;
const style = N.options && N.options.imageStyle ? ' Style: ' + N.options.imageStyle + '.' : '';
return (N.article.imagePrompts || []).map((p, i) => ({ json: {
  idx: Number.isFinite(Number(p.idx)) ? Number(p.idx) : i,
  placement: p.placement || (i === 0 ? 'hero' : 'after_h2:' + i),
  alt: String(p.alt || N.article.title || ''),
  aspect: i === 0 ? '16:9' : '4:3',
  prompt: String(p.prompt) + style + ' No text, no letters, no watermark, no logo.',
  slug: String(N.article.slug || 'artikel'),
} }));

// Fase 6 — Ambil base64 dari respons Gemini image per item, gabungkan ke payload publish (images[]), lanjut ke CMS Router.
const N = JSON.parse(JSON.stringify($('Auth & Normalize (Publish)').first().json));
const prompts = $('Siapkan Prompt Gambar').all().map(i => i.json);
const resps = $input.all().map(i => i.json || {});
const images = []; const failed = [];
resps.forEach((res, i) => {
  const meta = prompts[i] || {};
  const parts = (((res.candidates || [])[0] || {}).content || {}).parts || [];
  const img = parts.find(p => (p.inlineData && p.inlineData.data) || (p.inline_data && p.inline_data.data));
  if (!img) { failed.push(meta.idx); return; }
  const d = img.inlineData || img.inline_data;
  const mime = d.mimeType || d.mime_type || 'image/png';
  const ext = mime.includes('jpeg') ? 'jpg' : mime.includes('webp') ? 'webp' : 'png';
  images.push({ idx: meta.idx, placement: meta.placement, alt: meta.alt, mime, b64: d.data, filename: meta.slug + '-' + (meta.idx === 0 ? 'hero' : 'img-' + meta.idx) + '.' + ext });
});
if (failed.length) N.warnings.push('Gambar gagal dibuat untuk idx ' + failed.join(', ') + (resps.find(r => r.error) ? ': ' + String((resps.find(r => r.error).error || {}).message || '').slice(0, 120) : '') + '.');
// buang placeholder yang gambarnya gagal
const ok = new Set(images.map(i => i.idx));
N.article.bodyMarkdown = String(N.article.bodyMarkdown || '').replace(/^\s*!\[([^\]]*)\]\(markimate:image:(\d+)\)\s*$/gm, (m, alt, idx) => (ok.has(Number(idx)) ? m : '')).replace(/\n{3,}/g, '\n\n');
N.images = images;
return [{ json: N }];

// Samakan format hasil adapter + tentukan HTTP code
const r = $input.first().json || {};
const ok = r.status === 'ok' || r.status === 'success';
return [{ json: {
  status: ok ? 'ok' : 'error',
  statusCode: ok ? 200 : (r.httpStatus && r.httpStatus >= 400 && r.httpStatus < 500 ? 400 : 502),
  cmsType: r.cmsType || $('Auth & Normalize (Publish)').first().json.cmsType,
  action: r.action || $('Auth & Normalize (Publish)').first().json.action,
  postId: r.postId || r.draftDocId || '',
  postStatus: r.postStatus || (ok ? ($('Auth & Normalize (Publish)').first().json.action === 'publish' ? 'publish' : 'draft') : ''),
  draftEditUrl: r.draftEditUrl || '',
  publicUrl: r.publicUrl || '',
  previewUrl: r.previewUrl || '',
  title: r.title || '',
  message: r.message || (ok ? 'Berhasil.' : 'Gagal mengirim ke CMS.'),
  images: Array.isArray(r.images) ? r.images : [],
  warnings: [...new Set([...($('Auth & Normalize (Publish)').first().json.warnings || []), ...(Array.isArray(r.warnings) ? r.warnings : [])])],
  requestId: r.requestId || $('Auth & Normalize (Publish)').first().json.requestId,
} }];

// Fase 6 — Endpoint TOPIK OTOMATIS: validasi & normalisasi input
// Body: { seedKeywords:[...], Geo, Ln, cmsType?, cms?, limit?, minVolume?, duplicateThreshold?, requestId? }
const body = $json.body || {};
const seeds = [...new Set((Array.isArray(body.seedKeywords) ? body.seedKeywords : String(body.seedKeywords || body.keyword || '').split(',')).map(s => String(s || '').trim().toLowerCase()).filter(Boolean))].slice(0, 10);
let statusCode = 200, error = '';
if (!seeds.length) { statusCode = 400; error = 'Field "seedKeywords" wajib diisi (array, maks 10).'; }
const n = (v, d, lo, hi) => { const x = Number(v); return Number.isFinite(x) ? Math.min(Math.max(x, lo), hi) : d; };
return [{ json: {
  ok: statusCode === 200, statusCode, error,
  seeds,
  geo: String(body.Geo || body.geo || 'ID').toUpperCase(), ln: String(body.Ln || body.ln || 'id').toLowerCase(),
  cmsType: ['wordpress', 'wix', 'sanity', 'shopify'].includes(String(body.cmsType || '').toLowerCase()) ? String(body.cmsType).toLowerCase() : '',
  cms: body.cms && typeof body.cms === 'object' ? body.cms : {},
  limit: n(body.limit, 3, 1, 10), minVolume: n(body.minVolume, 50, 0, 100000), duplicateThreshold: n(body.duplicateThreshold, 0.7, 0.4, 0.95),
  siteBaseUrl: String((body.options || {}).siteBaseUrl || body.siteBaseUrl || '').trim(),
  requestId: String(body.requestId || ('top_' + Date.now().toString(36))),
} }];

// Fase 6 — Ambil artikel yang sudah ada (untuk dedupe) lalu keluarkan satu item per seed keyword untuk riset Trends
const N = $input.first().json;
const H = this.helpers;
// ===== Helper CMS bersama (disisipkan oleh build-workflows.mjs) =====
// listExistingPosts(H, cmsType, cms, opts) -> [{ title, slug, url, publishedAt }]
// H = this.helpers (Code node). Semua error ditelan → [] supaya alur artikel tidak mati.
async function listExistingPosts(H, cmsType, cms, opts) {
  const o = Object.assign({ limit: 200, siteBaseUrl: '' }, opts || {});
  const base = String(o.siteBaseUrl || '').trim();
  const urlOf = (slug, direct) => direct || (base && slug ? base.replace(/\/+$/, '') + '/' + slug : '');
  const c = (cms || {})[cmsType] || {};
  try {
    if (cmsType === 'sanity') {
      const q = '*[_type == $t && defined(slug.current)] | order(coalesce(publishedAt, _createdAt) desc) [0...' + o.limit + ']{title, "slug": slug.current, publishedAt}';
      const r = await H.httpRequest({ method: 'POST', url: 'https://' + c.projectId + '.api.sanity.io/v2025-02-19/data/query/' + encodeURIComponent(c.dataset || 'production'),
        headers: Object.assign({ 'Content-Type': 'application/json' }, c.token ? { Authorization: 'Bearer ' + c.token } : {}), body: { query: q, params: { t: c.docType || 'post' } }, json: true });
      const pat = String(c.publicUrlPattern || '');
