// --- kemiripan topik (token Jaccard-ish, dipakai cek duplikat & dedupe kandidat) ---
const STOPWORDS = new Set(['apa', 'itu', 'adalah', 'yang', 'dan', 'di', 'ke', 'dari', 'untuk', 'dengan', 'pada', 'cara', 'tips', 'panduan', 'lengkap', 'pengertian', 'arti', 'what', 'is', 'the', 'a', 'an', 'of', 'to', 'for', 'and', 'in', 'how', '2024', '2025', '2026', '2027', 'terbaru', 'contoh', 'jenis', 'manfaat', 'strategi', 'bisnis', 'agar', 'bagi', 'vs', 'atau']);
const topicTokens = s => String(s || '').toLowerCase().replace(/[^a-z0-9\s-]/g, ' ').replace(/-/g, ' ').split(/\s+/).filter(t => t.length > 1 && !STOPWORDS.has(t));
function topicSimilarity(a, b) {
  const ta = [...new Set(topicTokens(a))], tb = new Set(topicTokens(b));
  if (!ta.length || !tb.size) return 0;
  return ta.filter(t => tb.has(t)).length / ta.length;
}
function findDuplicate(keyword, posts, threshold) {
  let best = null;
  for (const p of posts || []) {
    const sim = Math.max(topicSimilarity(keyword, p.title), topicSimilarity(keyword, String(p.slug || '').replace(/-/g, ' ')));
    if (sim >= (threshold || 0.7) && (!best || sim > best.similarity)) best = Object.assign({ similarity: Number(sim.toFixed(2)) }, p);
  }
  return best;
}

const stop = new Set(['di', 'ke', 'dari', 'yang', 'dan', 'untuk', 'dengan', 'ada', 'adalah', 'itu', 'ini', 'cara', 'tips', 'info', 'the', 'a', 'an', 'of', 'for', 'in', 'on', 'to']);
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const skipped = { duplicate: 0, noMatch: 0, trendsError: 0 };
const cands = []; const seen = new Set();
resps.forEach((t, i) => {
  const seed = (seeds[i] || {}).seed || '';
  if (t.error) skipped.trendsError++;
  const rq = t.related_queries || {};
  const pool = [...(rq.rising || []).map(x => ({ q: x.query, src: 'trends_rising', v: x.extracted_value || 0 })), ...(rq.top || []).map(x => ({ q: x.query, src: 'trends_top', v: x.extracted_value || 0 }))];
  const terms = [seed, ...seed.split(/\s+/).map(w => w.replace(/[^a-z0-9]/g, '')).filter(w => w.length > 2 && !stop.has(w))];
  const matches = q => terms.some(tm => tm.includes(' ') ? q.includes(tm) : new RegExp('\\b' + esc(tm) + '\\b', 'i').test(q));
  for (const p of pool) {
    const q = String(p.q || '').trim().toLowerCase();
    if (!q || q === seed || seen.has(q)) continue;
    if (!matches(q)) { skipped.noMatch++; continue; }
    if (findDuplicate(q, existing, N.duplicateThreshold)) { skipped.duplicate++; continue; }
    if (cands.some(c => topicSimilarity(q, c.query) >= N.duplicateThreshold)) { skipped.duplicate++; continue; }
    seen.add(q); cands.push({ query: q, seed, source: p.src, trendValue: Number(p.v) || 0 });
  }
});
const out = cands.slice(0, Math.max(N.limit * 4, 8)).map(c => ({ json: Object.assign(c, { skipped, geoLower: N.geo.toLowerCase() }) }));
return out.length ? out : [{ json: { query: '', empty: true, skipped, geoLower: N.geo.toLowerCase() } }];

// Fase 6 — Gabungkan metrik Ahrefs ke kandidat, saring volume minimum, urutkan, batasi jumlah → respons
const N = $('Auth & Normalize (Topics)').first().json;
const cands = $('Kumpulkan Kandidat').all().map(i => i.json);
const metrics = $input.all().map(i => i.json || {});
const num = v => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const skipped = Object.assign({ duplicate: 0, noMatch: 0, trendsError: 0 }, (cands[0] || {}).skipped || {}, { lowVolume: 0 });
const rows = [];
cands.forEach((c, i) => {
  if (c.empty) return;
  const m = metrics[i] || {}; const d = m.data || m || {};
  const vol = num(d.globalSearchVolume ?? d.searchVolume ?? d.volume);
  if (vol < N.minVolume) { skipped.lowVolume++; return; }
  rows.push({ keyword: c.query, seed: c.seed, source: c.source, searchVolume: vol, difficulty: (d.difficulty === null || d.difficulty === undefined || d.difficulty === '') ? null : num(d.difficulty), trafficPotential: num(d.trafficPotential), trendValue: c.trendValue });
});
rows.sort((a, b) => (b.source === 'trends_rising') - (a.source === 'trends_rising') || b.searchVolume - a.searchVolume);
return [{ json: { status: 'ok', statusCode: 200, topics: rows.slice(0, N.limit), candidatesChecked: cands.filter(c => !c.empty).length, skipped, requestId: N.requestId } }];
